        assertTrue(created.get("guestCpf").isNull());
        assertEquals("Tecnosul Ltda", created.get("companyName").asText());
        assertTrue(created.get("guestPassport").isNull());
        long id = created.get("id").asLong();
        post("\/reservations\/" + id + "\/confirmation", "");

        JsonNode document = json.readTree(get("\/reservations\/" + id + "\/document").body());
        assertEquals("Fatura de hospedagem", document.get("title").asText());
        assertEquals("12.345.678\/0001-90", document.get("companyCnpj").asText());
        assertTrue(document.get("guestCountry").isNull());
        assertTrue(document.get("text").asText().contains("ISS retido (5%): R\$ 46,79"));

        String passport = RESERVATION_JSON.replace("\\"guestCpf\\": \\"111.222.333-44\\"",
                "\\"guestPassport\\": \\"X1234567\\", \\"guestCountry\\": \\"Chile\\"").replace("07-1", "08-1");
        HttpResponse<String> foreign = post("\/reservations", passport);
        assertEquals(201, foreign.statusCode());
        assertEquals("Chile", json.readTree(foreign.body()).get("guestCountry").asText());
    }

    \@Test
    void requiresExactlyOneWayToIdentifyTheGuest() throws Exception {
        String none = RESERVATION_JSON.replace("\\"guestCpf\\": \\"111.222.333-44\\",", "");
        String two = RESERVATION_JSON.replace("\\"guestCpf\\"",
                "\\"guestPassport\\": \\"X1\\", \\"guestCountry\\": \\"Chile\\", \\"guestCpf\\"");
        String half = none.replace("\\"checkIn\\"", "\\"companyCnpj\\": \\"1\\", \\"checkIn\\"");
        for (String body : new String[] {none, two, half}) {
            HttpResponse<String> response = post("\/reservations", body);
            assertEquals(400, response.statusCode());
            assertEquals("INVALID_REQUEST", json.readTree(response.body()).get("error").asText());
        }
    }

